function subjectView(id){const s=subjects.find(x=>x.id===id); if(!s)return head('Subject not found','Choose a subject to get started.'); return `${head(s.name,'A small start is still a start. Explore your starter topic below.')}<div class="content-card">${subjectIcon(s)}<p class="eyebrow" style="margin-top:20px">STARTER TOPIC</p><h2>${s.topic}</h2><p>${s.note}</p><div class="topic-list"><div class="topic-row"><div><strong>Quick knowledge check</strong><small>One question · instant explanation</small></div><a class="btn dark" href="#quiz/${s.id}">${state.completed[s.id]?'Try again':'Start quiz'} →</a></div><div class="topic-row"><div><strong>Recall flashcards</strong><small>${starterDecks.find(deck=>deck.id===s.id).cards.length} cards · flip and review</small></div><button class="btn outline" data-deck="${s.id}">Review cards →</button></div><div class="topic-row"><div><strong>More ${s.name} flashcards</strong><small>Browse all available sets</small></div><button class="btn outline" data-open-subject="${s.name}">Browse sets →</button></div><div class="topic-row"><div><strong>Video lessons</strong><small>Explore external video resources</small></div><button class="btn outline" data-open-video-subject="${s.name}">Find videos →</button></div></div><p style="font-size:11px;margin-top:20px">These are introductory revision materials, not a complete exam specification. Check your exam board for full coverage.</p></div>`;}
function quizView(id){const s=subjects.find(x=>x.id===id); if(!s)return '';return `${head('Quick knowledge check',`${s.name} · ${s.topic}`)}<div class="content-card"><p class="eyebrow">QUESTION 1 OF 1</p><h2>${s.question}</h2><div id="answers">${s.options.map((o,i)=>`<button class="quiz-option" data-answer="${i}" data-subject="${s.id}">${String.fromCharCode(65+i)} &nbsp; ${o}</button>`).join('')}</div><div id="feedback" role="status" aria-live="polite"></div><a href="#subject/${s.id}" class="text-link">← Back to topic</a></div>`;}
function subjectTiles() {
  return selectedSubjects().map(name=>{
    const existing=subjects.find(s=>s.name===name);
    const count=allDecks().filter(d=>d.subject===name).length;
    if(existing) return subjectCard(existing);
    return `<button class="subject-card" data-open-subject="${escapeHTML(name)}"><div class="subject-top"><span class="subject-icon mint" aria-hidden="true">▧</span><span class="subject-arrow">↗</span></div><h3>${escapeHTML(name)}</h3><p>${count ? `${count} flashcard ${count===1?'set':'sets'} available` : 'No ready-made sets yet'}</p><div class="progress-label"><span>${count?'Browse your sets':'Create the first set'}</span></div></button>`;
  });
}
function subjectChooser(selected = []) {
  const choices=[...new Set([...subjectCatalog,...selected])];
  return `<div class="subject-picker"><label class="field">Search subjects<input type="search" class="subject-search" placeholder="Search subjects..." autocomplete="off"></label><div class="subject-options">${choices.map(name=>`<label class="subject-option" data-subject-label="${escapeHTML(name.toLowerCase())}"><input type="checkbox" name="subjects" value="${escapeHTML(name)}" ${selected.includes(name)?'checked':''}><span>${escapeHTML(name)}</span></label>`).join('')}</div><label class="field">Can't find yours? Add a subject<input type="text" name="customSubject" maxlength="80" placeholder="e.g. Film Studies"></label><p class="subject-help">Choose at least one subject. You can change these later. Some subjects don't have starter sets yet.</p></div>`;
}
function subjectsPage() {
  return `${head('My subjects','Your workspace, shaped around what you study.')}<div class="subjects all-subjects">${subjectTiles().join('')}</div><div class="content-card subject-settings"><h2>Choose your subjects</h2><p>Select the subjects you study. Your choices are saved to your account.</p><form id="subjectsForm">${subjectChooser(selectedSubjects())}<p class="error" id="subjectsError" role="alert"></p><button class="btn dark" type="submit">Save my subjects →</button></form></div>`;
}
function onboarding() {
  return `${head('Make this space yours','Choose the subjects you study. You can change these any time.')}<div class="content-card subject-settings"><form id="subjectsForm">${subjectChooser(selectedSubjects())}<p class="error" id="subjectsError" role="alert"></p><button class="btn dark" type="submit">Build my workspace →</button></form></div>`;
}
function normalizeSet(row) {
  if (!row || typeof row.id!=='string' || !/^[0-9a-f-]{36}$/i.test(row.id) || typeof row.title!=='string' || typeof row.subject!=='string' || !Array.isArray(row.cards)) return null;
  const cards=row.cards.filter(c=>Array.isArray(c)&&c.length===2&&c.every(v=>typeof v==='string'&&v.trim())).slice(0,50).map(c=>c.map(v=>v.slice(0,1000)));
  if(!cards.length)return null;
  return {id:`set-${row.id}`, databaseId:row.id, ownerId:row.owner_id, title:row.title.slice(0,100),subject:row.subject.slice(0,80),description:typeof row.description==='string'?row.description.slice(0,300):'',color:'mint',cards,isPublic:!!row.is_public,community:true};
}
async function loadCommunitySets() { communityDecks=(await backend.listSets(user.id)).map(normalizeSet).filter(Boolean); }
function createSetPage() {
  return `${head('Create a flashcard set','Make a set for yourself, or share it with other signed-in learners.')}<div class="content-card creator"><form id="createSetForm"><label class="field">Set title<input name="title" required maxlength="100" placeholder="e.g. French food vocabulary"></label><label class="field">Subject<select name="subject" required>${selectedSubjects().map(x=>`<option value="${escapeHTML(x)}">${escapeHTML(x)}</option>`).join('')}</select></label><label class="field">Description (optional)<input name="description" maxlength="300" placeholder="What will this set cover?"></label><details class="bulk-import"><summary>Paste a list of cards</summary><p>Paste one question and answer per line, separated by a tab (for example, from a spreadsheet). This replaces the draft cards below; nothing is saved until you create the set.</p><label class="field" for="bulkCards">Questions and answers<textarea id="bulkCards" rows="5" placeholder="Question [tab] Answer"></textarea></label><p class="error" id="importError" role="alert"></p><button type="button" class="btn outline" id="importCards">Add pasted cards →</button></details><div class="creator-head"><h2>Your cards</h2><span>Up to 50 cards</span></div><p>Add a question and answer for each card.</p><div id="creatorCards">${creatorCard(1)}${creatorCard(2)}</div><button type="button" class="btn outline" id="addCreatorCard">+ Add a card</button><label class="visibility-choice"><input type="checkbox" name="isPublic"><span><strong>Make this set public</strong><small>Other signed-in learners can see and use it. Leave unchecked to keep it private.</small></span></label><p class="error" id="createError" role="alert"></p><button class="btn dark" type="submit">Create set →</button></form></div>`;
}
function creatorCard(index) { return `<div class="creator-card"><div><strong>Card ${index}</strong><button type="button" class="remove-creator-card" aria-label="Remove card">Remove</button></div><label class="field">Question<textarea name="question" rows="2" maxlength="1000" required placeholder="Write a question"></textarea></label><label class="field">Answer<textarea name="answer" rows="2" maxlength="1000" required placeholder="Write the answer"></textarea></label></div>`; }
function deckCard(deck) {
  const done=deck.cards.filter((_,i)=>state.reviews[`${deck.id}-${i}`]).length;
  return `<a class="deck-card" href="#flashcards/${escapeHTML(deck.id)}"><span class="deck-symbol ${escapeHTML(deck.color)}" aria-hidden="true">▤</span><span class="deck-info"><span class="deck-subject">${escapeHTML(deck.subject)}</span><strong>${escapeHTML(deck.title)}</strong><span class="deck-description">${escapeHTML(deck.description)}</span></span><span class="deck-meta"><span>${deck.cards.length} cards</span><span>${deck.community ? (deck.isPublic?'Community · public':'Your private set') : (done ? `${done} reviewed` : 'Starter set')}</span></span><span class="deck-open" aria-hidden="true">→</span></a>`;
}
function deckResults() {
  const available=deckSubject==='My subjects'?allDecks().filter(d=>selectedSubjects().includes(d.subject)):allDecks();
  const results=searchDecks(available,deckQuery,['My subjects','All subjects'].includes(deckSubject)?'All':deckSubject);
  const grid=$('#deckResults'); if(!grid)return;
  $('#resultsCount').textContent=`${results.length} ${results.length===1?'set':'sets'}`;
  grid.innerHTML=results.length?results.map(deckCard).join(''):'<div class="deck-empty"><strong>No sets found</strong><p>Try a different word or choose another subject.</p><button class="btn outline" id="clearSearch">Clear filters</button></div>';
  document.querySelectorAll('[data-filter]').forEach(b=>{const active=b.dataset.filter===deckSubject;b.classList.toggle('selected',active);b.setAttribute('aria-pressed',String(active));});
}
function flashcardLibrary() {
  const categories=['My subjects','All subjects',...selectedSubjects()];
  return `<div class="library-heading"><div><p class="eyebrow">YOUR LIBRARY</p><h1>Flashcard sets</h1><p>Choose a set to study cards, play games or take a practice test.</p><span class="library-count">${allDecks().length} available sets · ${allDecks().reduce((total,deck)=>total+deck.cards.length,0)} cards</span></div><a class="btn dark" href="#create-set">+ Create a set</a></div>
  <div class="library-actions"><span>Showing up to 100 of your sets and 100 public sets. Community sets are not reviewed.</span></div><div class="library-tools"><label class="search-label" for="deckSearch">Search flashcard sets</label><div class="search-wrap"><span aria-hidden="true">⌕</span><input id="deckSearch" type="search" placeholder="Search subjects, sets or card content..." value="${escapeHTML(deckQuery)}" autocomplete="off"></div><div class="filter-row" aria-label="Filter by subject">${categories.map(c=>`<button class="filter-chip ${deckSubject===c?'selected':''}" data-filter="${escapeHTML(c)}" aria-pressed="${deckSubject===c}">${escapeHTML(c)}</button>`).join('')}</div></div>
  <div class="section-head library-section"><div><h2>Sets</h2><p>Starter cards are introductory; check your exam specification for full coverage.</p></div><span id="resultsCount" class="results-count" aria-live="polite"></span></div><div class="deck-grid" id="deckResults"></div>`;
}
function deckOverview(deck) {
  const done=deck.cards.filter((_,i)=>state.reviews[`${deck.id}-${i}`]).length;
  const visibility=deck.community?(deck.isPublic?'Community set · unreviewed':'Your private set'):'Starter set';
  return `<div class="set-header"><a class="back-link" href="#flashcards">← All sets</a><div class="set-header-main"><span class="set-cover ${escapeHTML(deck.color)}" aria-hidden="true">▤</span><div><p class="set-subject">${escapeHTML(deck.subject)}</p><h1>${escapeHTML(deck.title)}</h1><p>${escapeHTML(deck.description)}</p><div class="set-meta"><span>${deck.cards.length} cards</span><span>${done} reviewed</span><span>${visibility}</span></div>${deck.community && deck.ownerId===user.id?`<div class="set-management"><button class="text-link" data-set-id="${escapeHTML(deck.databaseId)}" data-set-visibility="${!deck.isPublic}">${deck.isPublic?'Make private':'Make public'}</button><button class="text-link delete-set" data-delete-set="${escapeHTML(deck.databaseId)}">Delete set</button></div>`:''}</div></div></div>
  <section class="set-options" aria-labelledby="setOptionsTitle"><div class="set-section-title"><div><h2 id="setOptionsTitle">Study this set</h2><p>Choose how you want to practise.</p></div></div><div class="set-mode-grid"><a class="set-mode" href="#flashcards/${escapeHTML(deck.id)}/study"><span class="mode-icon mode-cards" aria-hidden="true">▤</span><span><strong>Flashcards</strong><small>Flip through this set</small></span><span class="mode-arrow" aria-hidden="true">→</span></a><a class="set-mode" href="#games/${escapeHTML(deck.id)}"><span class="mode-icon mode-games" aria-hidden="true">◈</span><span><strong>Games &amp; quiz</strong><small>Practise with instant feedback</small></span><span class="mode-arrow" aria-hidden="true">→</span></a><a class="set-mode" href="#tests/${escapeHTML(deck.id)}"><span class="mode-icon mode-test" aria-hidden="true">✓</span><span><strong>Practice test</strong><small>Answer, then check your results</small></span><span class="mode-arrow" aria-hidden="true">→</span></a><a class="set-mode mode-live-link" href="#live/host/${escapeHTML(deck.id)}"><span class="mode-icon mode-live" aria-hidden="true">▦</span><span><strong>Play live</strong><small>Host or join friends</small></span><span class="mode-arrow" aria-hidden="true">→</span></a></div></section>
  <section class="set-card-preview" aria-labelledby="setCardsTitle"><div class="set-section-title"><div><h2 id="setCardsTitle">Cards in this set <span>${deck.cards.length}</span></h2><p>Open an answer to take a look.</p></div><a class="text-link" href="#flashcards/${escapeHTML(deck.id)}/study">Study cards →</a></div><div class="set-card-list">${deck.cards.map((card,i)=>`<details class="set-preview-card"><summary><span class="set-card-index">${String(i+1).padStart(2,'0')}</span><strong>${escapeHTML(card[0])}</strong><span class="set-card-toggle" aria-hidden="true">+</span></summary><div class="set-card-answer"><span>ANSWER</span><p>${escapeHTML(card[1])}</p></div></details>`).join('')}</div></section>`;
}
function flashcards(id, view) {
  const deck=allDecks().find(d=>d.id===id);
  if(!deck) return `${head('Set not found','Choose another flashcard set to get started.')}<a class="btn dark" href="#flashcards">Browse sets →</a>`;
  if(selectedDeck!==id){selectedDeck=id;cardIndex=0;cardFlipped=false;}
  if(view!=='study') return deckOverview(deck);
  const card=deck.cards[cardIndex] || deck.cards[0];
  const done=deck.cards.filter((_,i)=>state.reviews[`${deck.id}-${i}`]).length;
  return `<div class="study-heading"><a class="back-link" href="#flashcards/${escapeHTML(deck.id)}">← Back to set</a><p class="eyebrow">${escapeHTML(deck.subject)} · FLASHCARDS</p><h1>${escapeHTML(deck.title)}</h1><p>${escapeHTML(deck.description)}</p>${deck.community?`<p class="set-visibility">${deck.isPublic?'Community set · public to signed-in learners':'Your private set'}</p>${deck.ownerId===user.id?`<button class="text-link" data-set-id="${escapeHTML(deck.databaseId)}" data-set-visibility="${!deck.isPublic}">${deck.isPublic?'Make private':'Make public'}</button> <button class="text-link delete-set" data-delete-set="${escapeHTML(deck.databaseId)}">Delete this set</button>`:''}`:''}</div><div class="study-game-link"><a class="btn outline" href="#games/${escapeHTML(deck.id)}">Games &amp; quick quiz →</a><a class="btn dark" href="#tests/${escapeHTML(deck.id)}">✓ Practice test →</a></div><div class="study-layout"><div class="content-card flashcard"><div class="study-progress"><span>Card ${cardIndex+1} of ${deck.cards.length}</span><strong>${done} / ${deck.cards.length} reviewed</strong></div><div class="bar"><span style="width:${Math.round(done/deck.cards.length*100)}%"></span></div><p class="eyebrow card-side">${cardFlipped?'ANSWER':'QUESTION'} <span>· TAP TO FLIP</span></p><button class="flashcard-face" id="flipCard"><span>${escapeHTML(cardFlipped?card[1]:card[0])}</span><span class="sr-only">${cardFlipped?'Show question':'Reveal answer'}</span></button><p class="flip-hint">${cardFlipped?'Think you have it? Mark it reviewed.':'Think of your answer, then tap the card to reveal it.'}</p><div class="flashcard-controls"><button class="btn outline" id="prevCard">← Previous</button><button class="btn dark" id="reviewCard">${state.reviews[`${deck.id}-${cardIndex}`]?'Reviewed ✓':'Mark reviewed ✓'}</button><button class="btn outline" id="nextCard">Next →</button></div></div><aside class="card-list"><div class="card-list-head"><h2>In this set</h2><span>${deck.cards.length} cards</span></div><p>Jump to any card below.</p><div class="card-list-scroll">${deck.cards.map((c,i)=>`<button class="card-list-item ${i===cardIndex?'current':''}" data-card-index="${i}" ${i===cardIndex?'aria-current="true"':''}><span class="card-number">${String(i+1).padStart(2,'0')}</span><span>${escapeHTML(c[0])}</span><span class="card-done">${state.reviews[`${deck.id}-${i}`]?'✓':''}</span></button>`).join('')}</div></aside></div>`;
}
function planner(){
 const tasks=sortedTasks(state.tasks),active=tasks.filter(({task})=>!task.done),completed=tasks.filter(({task})=>!!task.done),remaining=active.length;
 return `<div class="tasks-page"><header class="tasks-header"><div class="tasks-heading-icon" aria-hidden="true">${taskSvg('<circle cx="12" cy="12" r="9"/><path d="m8 12 3 3 6-6"/>')}</div><div><p class="tasks-kicker">YOUR WORKSPACE</p><h1>Tasks</h1><p>${remaining} ${remaining===1?'task':'tasks'} to do</p></div></header><section class="tasks-workspace" aria-labelledby="taskListHeading"><div class="tasks-list-heading"><div><h2 id="taskListHeading">My tasks</h2><p>Keep track of what you need to do.</p></div></div><div class="tasks-tabs" role="group" aria-label="Filter tasks"><button type="button" data-task-filter="all" aria-pressed="true">All</button><button type="button" data-task-filter="open" aria-pressed="false">To do</button><button type="button" data-task-filter="starred" aria-pressed="false">Starred</button><button type="button" data-task-filter="done" aria-pressed="false">Completed</button></div><button type="button" id="taskAddButton" class="tasks-add">${taskSvg('<path d="M12 5v14M5 12h14"/>')}<span>Add a task</span></button><form id="planForm" class="tasks-composer" hidden><input type="hidden" name="index" value=""><h3 id="taskFormTitle">New task</h3><label class="tasks-form-label" for="taskTitle">Task name</label><input id="taskTitle" name="title" required maxlength="100" placeholder="What do you need to do?" autocomplete="off"><label class="tasks-form-label" for="taskDate">Date <span>(optional)</span></label><input id="taskDate" name="date" type="date"><div class="tasks-composer-actions"><button type="button" id="planCancel" class="tasks-cancel">Cancel</button><button class="tasks-save" type="submit">Save</button></div></form><div id="taskOpenSection"><div class="tasks-section-title"><h3>To do</h3><span>${remaining}</span></div><div id="taskOpenRows">${active.map(({task,index})=>taskHTML(task,index)).join('')}</div></div><section id="taskCompletedSection"><button type="button" id="taskCompletedToggle" class="tasks-completed-toggle" aria-expanded="true" aria-controls="taskCompletedRows">${taskSvg('<path d="m7 10 5 5 5-5"/>')}<span>Completed (<span id="taskCompletedCount">${completed.length}</span>)</span></button><div id="taskCompletedRows">${completed.map(({task,index})=>taskHTML(task,index)).join('')}</div></section><div id="taskFilterEmpty" class="tasks-empty" hidden><div class="tasks-empty-icon" aria-hidden="true">${taskSvg('<path d="M5 6h14M5 12h14M5 18h9"/>')}</div><strong>Nothing here yet</strong><p id="taskFilterEmptyText"></p></div></section></div>`;
}
function gameResults() {
  const grid=$('#gameSetGrid'); if(!grid)return;
  const available=gameSubject==='My subjects'?allDecks().filter(deck=>selectedSubjects().includes(deck.subject)):allDecks();
  const results=searchDecks(available,gameQuery,['My subjects','All subjects'].includes(gameSubject)?'All':gameSubject);
  $('#gameResultsCount').textContent=`${results.length} ${results.length===1?'set':'sets'}`;
  grid.innerHTML=gameSetCards(results);
  document.querySelectorAll('[data-game-filter]').forEach(button=>{const active=button.dataset.gameFilter===gameSubject;button.classList.toggle('selected',active);button.setAttribute('aria-pressed',String(active));});
}
function gamesPage(id) {
  if (!id) {
    const categories=['My subjects','All subjects',...selectedSubjects()];
    if(!categories.includes(gameSubject)) gameSubject='My subjects';
    return gamesHub(categories,gameSubject,gameQuery);
  }
  const deck=allDecks().find(item=>item.id===id);
  if(!deck)return `${head('Set not found','Choose another set to play a game.')}<a class="btn dark" href="#games">Browse games →</a>`;
  if(gameSession?.deckId===id) return gameView(deck,gameSession);
  return gameChooser(deck,uniqueGameCards(deck.cards).length);
}
function announceGame(message){$('#gameAnnouncer').textContent=message;}
function renderGame(focus, message) {
  render();
  if(focus) document.querySelector(focus)?.focus({preventScroll:true});
  if(message) announceGame(message);
}
function completeGame(){record();const gained=awardActivity('game');save();if(gained)toast(`Study game complete · +${gained} coins`);}
function testsPage(id){
  if(!id)return flashcardLibrary();
  const deck=allDecks().find(item=>item.id===id);
  if(!deck)return `${head('Set not found','Choose another set for a practice test.')}<a class="btn dark" href="#flashcards">Browse sets →</a>`;
  return testSession?.deckId===id?practiceView(deck,testSession):practiceChooser(deck,uniqueGameCards(deck.cards).length);
}
function renderPractice(focus,message){render();window.scrollTo(0,0);if(focus)document.querySelector(focus)?.focus({preventScroll:true});if(message)announceGame(message);}
function videosPage() {
  const categories=['My subjects','All subjects',...selectedSubjects()];
  if(!categories.includes(videoSubject)) categories.push(videoSubject);
  const discoveries=selectedSubjects().map(subject=>`<a class="video-discovery-link" href="https://www.youtube.com/results?${new URLSearchParams({search_query:subject+' revision tutorial'}).toString()}" target="_blank" rel="noopener noreferrer">${escapeHTML(subject)} <span aria-hidden="true">↗</span></a>`).join('');
  return `<div class="video-hero"><div><p class="eyebrow">WATCH &amp; LEARN</p><h1>Video lessons</h1><p>Find a lesson, then use a related flashcard set to practise.</p><span class="video-hero-note">▶ &nbsp; ${videos.length} selected lessons · watch here</span></div><div class="video-hero-art" aria-hidden="true"><div class="video-screen"><span>▶</span></div></div></div>
  <div class="library-tools video-tools"><label class="search-label" for="videoSearch">Search selected videos</label><div class="search-wrap"><span aria-hidden="true">⌕</span><input id="videoSearch" type="search" placeholder="Search a subject, topic or creator..." value="${escapeHTML(videoQuery)}" autocomplete="off" aria-controls="videoGrid"></div><div class="filter-row" aria-label="Filter videos by subject">${categories.map(c=>`<button class="filter-chip ${videoSubject===c?'selected':''}" data-video-filter="${escapeHTML(c)}" aria-pressed="${videoSubject===c}">${escapeHTML(c)}</button>`).join('')}</div></div>
  <div class="section-head video-section"><div><h2>Selected video lessons</h2><p>Choose a lesson to watch here. Thumbnails and video players are provided by YouTube; check your exam board.</p></div><span id="videoCount" class="results-count" aria-live="polite"></span></div><div id="videoGrid" class="video-grid"></div>
  <section class="video-discovery"><div><p class="eyebrow">LOOKING FOR MORE?</p><h2>Explore your subjects</h2><p>Search YouTube for more lessons in your subjects. Search results are not selected or reviewed by Everything Hub and may include adverts or paid services.</p></div><div class="video-discovery-links">${discoveries}</div></section>`;
}
function videoResults(){
  const grid=$('#videoGrid'); if(!grid)return;
  const results=filterVideos(videos,videoQuery,videoSubject,selectedSubjects());
  $('#videoCount').textContent=`${results.length} ${results.length===1?'video':'videos'}`;
  grid.innerHTML=results.length?results.map(v=>{
    const thumbnail=youtubeThumbnail(v.url);
    return `<a class="video-card" href="#videos/${escapeHTML(v.id)}"><div class="video-card-art">${thumbnail?`<img class="video-thumbnail" src="${escapeHTML(thumbnail)}" alt="" width="320" height="180" loading="lazy" decoding="async" referrerpolicy="no-referrer">`:''}<span class="video-play" aria-hidden="true">▶</span><span class="video-level">${escapeHTML(v.level)}</span><span class="video-open" aria-hidden="true">→</span></div><div class="video-card-body"><p class="video-subject">${escapeHTML(v.subjects[0])}</p><h3>${escapeHTML(v.title)}</h3><p>${escapeHTML(v.description)}</p><div class="video-card-meta"><span>${escapeHTML(v.creator)}</span><strong>Watch lesson →</strong></div></div></a>`;
  }).join(''):'<div class="deck-empty"><strong>No selected videos found</strong><p>Try another search or subject, or explore the YouTube searches below.</p><button class="btn outline" id="clearVideoSearch">Clear filters</button></div>';
  document.querySelectorAll('[data-video-filter]').forEach(button=>{const active=button.dataset.videoFilter===videoSubject;button.classList.toggle('selected',active);button.setAttribute('aria-pressed',String(active));});
}
function videoPlayer(id){
  const video=videos.find(item=>item.id===id);
  const embed=video && youtubeEmbed(video.url);
  const youtubeId=video && youtubeVideoId(video.url);
  if(!embed || !youtubeId) return `${head('Video not found','Choose another lesson from the video library.')}<a class="btn dark" href="#videos">← Back to videos</a>`;
  const deck=starterDecks.find(item=>item.id===videoPracticeDecks[id]);
  return `<div class="watch-heading"><a class="back-link" href="#videos">← Back to video lessons</a><p class="eyebrow">${escapeHTML(video.subjects[0])} · ${escapeHTML(video.level)}</p><h1>${escapeHTML(video.title)}</h1><p>${escapeHTML(video.description)}</p></div>
  <div class="watch-layout"><section class="watch-main" aria-label="Video lesson"><div class="video-player"><iframe src="${escapeHTML(embed)}" title="Video lesson: ${escapeHTML(video.title)}" width="640" height="360" loading="lazy" referrerpolicy="strict-origin-when-cross-origin" allow="accelerometer; clipboard-write; encrypted-media; gyroscope; picture-in-picture; web-share; fullscreen" allowfullscreen></iframe></div><div class="watch-source"><div><strong>${escapeHTML(video.creator)}</strong><p>Hosted by YouTube · Video availability, adverts and privacy are controlled by YouTube and the creator.</p></div><a class="btn outline" href="https://www.youtube.com/watch?v=${youtubeId}" target="_blank" rel="noopener noreferrer">Open on YouTube ↗</a></div><p class="watch-fallback">Video not playing? Some creators restrict embedding, or your browser may block the player. Use the YouTube link above instead.</p></section>
  <aside class="watch-aside"><div class="watch-tip"><p class="eyebrow">MAKE IT STICK</p><h2>Pause. Recall. Practise.</h2><p>After watching, try explaining the key idea without looking. Then check what you remembered.</p></div>${deck?`<div class="watch-practice"><p class="eyebrow">KEEP PRACTISING</p><h2>Try some flashcards</h2><p>A related ${escapeHTML(deck.subject)} set to help you review.</p><a class="practice-deck" href="#flashcards/${escapeHTML(deck.id)}"><span><strong>${escapeHTML(deck.title)}</strong><small>${deck.cards.length} cards · ${escapeHTML(deck.subject)}</small></span><span aria-hidden="true">↗</span></a></div>`:''}</aside></div>`;
}

