function updateAccount(){const name=user?user.name:'Guest learner';const pending=user && localStorage.getItem(pendingKey(user.id))==='1';const wallet=normalizeRewards(state.rewards);const badge=rewardsCatalog.find(item=>item.id===wallet.equipped)||rewardsCatalog[0];document.querySelectorAll('.avatar,.top-avatar').forEach(e=>{e.textContent=badge.id==='leaf'?name[0].toUpperCase():badge.symbol;e.dataset.badge=badge.color;});$('#topAccount').setAttribute('aria-label',pending?'Account: changes not synced':'Account');}

