function account(mode='login') {
  if(user) {
    const pending = localStorage.getItem(pendingKey(user.id)) === '1';
    modal({title:'Your account',body:`<p>Signed in as ${escapeHTML(user.name)} (${escapeHTML(user.email)}).</p>${pending ? `<p class="error">There are changes on this device that have not synced. Choose which copy to keep. Uploading replaces your cloud progress; using cloud progress discards local changes.</p><button class="btn dark" id="useLocal">Upload local progress</button><button class="btn outline" id="useCloud">Use cloud progress</button>` : '<p>Your account progress is saved to Supabase when you make changes. Your lists, notes, habits and other progress share the same account.</p>'}<p id="accountError" class="error" role="alert"></p><button class="btn outline" id="logout">Sign out</button>`});
    return;
  }
  modal({title:mode==='login'?'Welcome back':'Create your account',body:`<p>${backend?'Sign in to sync your hub across devices. You can choose subjects later if you use revision.':'Account setup is not complete yet. Please try again later.'}</p>${backend?`<form id="authForm" data-mode="${mode}">${mode==='register'?'<label class="field">Name<input name="name" required maxlength="60" autocomplete="name"></label>':''}<label class="field">Email<input name="email" type="email" required autocomplete="email"></label><label class="field">Password<input name="password" type="password" minlength="8" maxlength="128" required autocomplete="${mode==='login'?'current-password':'new-password'}"></label><p class="error" id="authError" role="alert"></p><button class="btn dark" type="submit">${mode==='login'?'Sign in':'Create account'}</button>${mode==='login'?'<button class="switch resend-confirmation" type="button" id="resendConfirmation">Resend confirmation email</button>':''}</form><p>${mode==='login'?'New here?':'Already have an account?'} <button class="switch" data-auth-mode="${mode==='login'?'register':'login'}">${mode==='login'?'Create an account':'Sign in'}</button></p>`:'<p>The site owner can follow the Supabase setup guide in the project README.</p>'}`});
}
