$('#app').addEventListener('input',e=>{if(e.target.id==='directorySearch'){const term=e.target.value.trim().toLocaleLowerCase();let count=0;document.querySelectorAll('[data-directory-item]').forEach(item=>{item.hidden=!item.dataset.search.includes(term);if(!item.hidden)count++;});document.querySelectorAll('[data-directory-group]').forEach(group=>{group.hidden=!group.querySelector('[data-directory-item]:not([hidden])');});$('#directoryStatus').textContent=`${count} ${count===1?'result':'results'}`;}if(e.target.id==='deckSearch'){deckQuery=e.target.value;deckResults();}if(e.target.id==='videoSearch'){videoQuery=e.target.value;videoResults();}if(e.target.id==='gameSearch'){gameQuery=e.target.value;gameResults();}if(e.target.classList.contains('subject-search'))filterSubjectOptions(e.target);});
$('#app').addEventListener('submit',async e=>{
if(e.target.id==='schoolLessonForm'){e.preventDefault();const data=new FormData(e.target),title=String(data.get('title')).trim(),day=Number(data.get('day')),time=String(data.get('time')),room=String(data.get('room')).trim();if(!title||title.length>80||!Number.isInteger(day)||day<0||day>6||!/^([01][0-9]|2[0-3]):[0-5][0-9]$/.test(time)||room.length>50){toast('Check your lesson details.');return;}if(!Array.isArray(state.schoolLessons))state.schoolLessons=[];const rawIndex=String(data.get('index'));if(rawIndex!==''){const index=Number(rawIndex);if(!Number.isInteger(index)||index<0||index>=state.schoolLessons.length){toast('Lesson not found.');return;}state.schoolLessons[index]={title,day,time,room};}else{if(state.schoolLessons.length>=60){toast('You have reached the lesson limit.');return;}state.schoolLessons.push({title,day,time,room});}save();render();toast('Lesson saved');return;}

if(e.target.id==='practiceStart'){e.preventDefault();const [page,id]=location.hash.slice(1).split('/');const deck=page==='tests'&&allDecks().find(item=>item.id===id);if(!deck)return;const count=Number(new FormData(e.target).get('length'));const test=createPractice(deck.cards,count);if(!test){toast('Choose a set with at least two distinct pairs.');return;}test.deckId=id;test.count=count;testSession=test;renderPractice('#practiceHeading','Practice test started.');return;}
if(e.target.id==='practiceForm' && testSession && !testSession.complete){e.preventDefault();const form=new FormData(e.target);const answers=testSession.questions.map((_,i)=>form.get(`question-${i}`));if(!submitPractice(testSession,answers)){$('#practiceError').textContent='Answer at least one question before submitting.';return;}record();const gained=awardActivity('test');save();renderPractice('#practiceHeading',`Test complete. ${testSession.score} out of ${testSession.questions.length} correct.`);if(gained)toast(`Practice test complete · +${gained} coins`);return;}
if(e.target.id==='recallForm'){e.preventDefault();if(!revealRecall(gameSession,$('#recallInput').value))return;renderGame('#recallRevealHeading',gameSession.message);return;}
if(e.target.id==='subjectsForm'){e.preventDefault();const chosen=subjectChoices(e.target);if(!chosen.length){$('#subjectsError').textContent='Please select at least one subject.';return;}state.subjects=chosen;deckSubject='My subjects';videoSubject='My subjects';videoQuery='';save();if(location.hash==='#subjects'||location.hash.startsWith('#live')||location.hash==='#chat')render();else location.hash='home';if(location.hash==='#home')render();toast('Subjects saved');return;}
if(e.target.id==='createSetForm'){e.preventDefault();const form=e.target;const data=new FormData(form);const qs=data.getAll('question');const answers=data.getAll('answer');const cards=qs.map((q,i)=>[String(q).trim(),String(answers[i]).trim()]);if(!cards.length||cards.length>50||cards.some(c=>!c[0]||!c[1])){$('#createError').textContent='Add a question and answer for every card.';return;}const title=String(data.get('title')).trim(),subject=String(data.get('subject'));if(!title||!selectedSubjects().includes(subject)){$('#createError').textContent='Add a title and choose one of your subjects.';return;}const button=form.querySelector('[type=submit]');button.disabled=true;try{const created=await backend.createSet({title,subject,description:String(data.get('description')).trim(),is_public:data.has('isPublic'),cards});await loadCommunitySets();location.hash=`flashcards/set-${created.id}`;toast('Flashcard set created');}catch(err){$('#createError').textContent=err.message||'Could not create your set.';button.disabled=false;}return;}
if(e.target.id!=='planForm')return;e.preventDefault();const data=new FormData(e.target);const title=String(data.get('title')).trim();if(!title){toast('Please enter a task');return;}const indexRaw=String(data.get('index'));const date=String(data.get('date'));if(indexRaw!==''){const index=Number(indexRaw);if(!Number.isInteger(index)||index<0||index>=state.tasks.length){toast('Task not found.');return;}state.tasks[index]={...state.tasks[index],title,date};}else{state.tasks.push({title,date,done:false});if(taskView==='done'||taskView==='starred')taskView='all';}save();render();$('#taskAddButton')?.focus();toast('Task saved');});
updateAccount();
if (backend) {
  try {
    const sessionUser=await backend.session();
    if (confirmationReturn) {
      if(confirmationHadToken && sessionUser) await backend.signOut();
      history.replaceState(null,'',location.pathname);
      showLanding();account('login');
      const msg=document.createElement('p');msg.className=confirmationHadToken && sessionUser?'auth-success':'error';msg.textContent=confirmationHadToken && sessionUser?'Email confirmed. Please sign in to continue.':'We could not confirm this link. Please try signing in or request a new confirmation email.';$('#authForm')?.prepend(msg);
    } else if(sessionUser) await enterAccount(sessionUser);
    else showLanding();
  } catch { showLanding(); if(confirmationReturn){history.replaceState(null,'',location.pathname);account('login');const msg=document.createElement('p');msg.className='error';msg.textContent='We could not verify this link. Please try signing in or request a new confirmation email.';$('#authForm')?.prepend(msg);}else toast('Could not connect to your account. Please try again.'); }
} else { showLanding(); }
document.querySelectorAll('[data-open-auth]').forEach(button=>button.disabled=false);
